const $=s=>document.querySelector(s);
const planets=[
{name:'Mercury',type:'Terrestrial',file:'mercury',color:'#b2aaa1',distance:57.9,temp:167,period:88,diameter:4879,gravity:3.7,tag:'Small world. Big extremes.',description:'The smallest planet travels around the Sun in just 88 Earth days. Its cratered surface preserves a history of impacts, while its extremely thin exosphere offers little protection from dramatic temperature swings.'},
{name:'Venus',type:'Terrestrial',file:'venus_surface',color:'#d6b77d',distance:108.2,temp:464,period:224.7,diameter:12104,gravity:8.9,tag:'A world wrapped in clouds.',description:'A thick atmosphere of carbon dioxide traps heat in a runaway greenhouse effect, making Venus the hottest planet. Its slow rotation runs in the opposite direction to most planets. This model reveals the surface beneath its clouds.'},
{name:'Earth',type:'Terrestrial',file:'earth',color:'#82add2',distance:149.6,temp:15,period:365.2,diameter:12756,gravity:9.8,tag:'Our pale blue dot.',description:'Our ocean-covered home is the only world known to support life. Liquid water, a protective atmosphere, and a magnetic field help make Earth a remarkable place in the solar system. From here, we look outward and wonder.'},
{name:'Mars',type:'Terrestrial',file:'mars',color:'#d39176',distance:228,temp:-65,period:687,diameter:6792,gravity:3.7,tag:'The next horizon.',description:'Iron minerals give the Red Planet its familiar rusty color. Mars has polar ice caps, the enormous volcano Olympus Mons, and evidence that liquid water once flowed across its surface. Robotic explorers continue to uncover its history.'},
{name:'Jupiter',type:'Gas giant',file:'jupiter',color:'#cbb597',distance:778.5,temp:-110,period:4331,diameter:142984,gravity:23.1,tag:'A giant among worlds.',description:'Jupiter is the largest planet in our solar system. Bands of clouds move through its turbulent atmosphere, where the Great Red Spot is a vast, long-lived storm. Beneath the visible clouds, pressure transforms the hydrogen-rich interior.'},
{name:'Saturn',type:'Gas giant',file:'saturn',color:'#d4c29b',distance:1432,temp:-140,period:10747,diameter:120536,gravity:9,tag:'The ringed wonder.',description:'Saturn’s bright rings consist of countless pieces of ice and rock. This gas giant is mostly hydrogen and helium and has an average density lower than water. Its remarkable moon system includes Titan, a world with a thick atmosphere.'},
{name:'Uranus',type:'Ice giant',file:'uranus',color:'#a0d2d5',distance:2867,temp:-195,period:30589,diameter:51118,gravity:8.7,tag:'A world turned sideways.',description:'Uranus rotates on its side, with an axis tilted about 98 degrees. Methane in its atmosphere absorbs red light and contributes to its blue-green appearance. This distant ice giant takes about 84 Earth years to orbit the Sun.'},
{name:'Neptune',type:'Ice giant',file:'neptune',color:'#6c90dd',distance:4515,temp:-200,period:59800,diameter:49528,gravity:11,tag:'At the edge of the known.',description:'Dark, cold, and swept by powerful winds, Neptune is the most distant planet from the Sun. Its atmosphere is rich in hydrogen and helium, with methane contributing to the blue color. One trip around the Sun takes about 165 Earth years.'}
];
let current=2,unit='C',motion=!matchMedia('(prefers-reduced-motion: reduce)').matches,orbitRunning=true,speed=3;
let updateModel=()=>{};
const format=n=>n.toLocaleString('en-US',{maximumFractionDigits:2});
const temp=n=>unit==='C'?n:Math.round(n*9/5+32);
$('#planet-picker').innerHTML=planets.map((p,i)=>`<button class="planet-button ${i===current?'selected':''}" data-planet="${i}" aria-pressed="${i===current}"><span class="mini-planet" style="background-image:url(assets/${p.file}.jpg)"></span>${p.name}</button>`).join('');
$('#orbit-legend').innerHTML=planets.map((p,i)=>`<button data-planet="${i}" class="${i===current?'selected':''}" aria-pressed="${i===current}" style="--planet-color:${p.color}"><i></i>${p.name}</button>`).join('');
function renderCharts(){
 $('#distance-chart').innerHTML=planets.map((p,i)=>`<button class="chart-row ${i===current?'selected':''}" data-planet="${i}" aria-label="Select ${p.name}, ${format(p.distance)} million kilometers from the Sun" aria-pressed="${i===current}"><span>${p.name}</span><span class="bar-track"><span class="distance-bar" style="--bar:${p.distance/4515*100}%;display:block"></span></span><span class="bar-value">${format(p.distance)}</span></button>`).join('');
 $('#temperature-chart').innerHTML=planets.map((p,i)=>`<button class="chart-row ${i===current?'selected':''}" data-planet="${i}" aria-label="Select ${p.name}, ${temp(p.temp)} degrees ${unit==='C'?'Celsius':'Fahrenheit'}" aria-pressed="${i===current}"><span>${p.name}</span><span class="temp-track"><span class="temp-point" style="--point:${(p.temp+220)/720*100}%;--point-color:${p.temp>100?'#dbab79':'#89b6ce'}"></span></span><span class="bar-value">${temp(p.temp)}°</span></button>`).join('');
 $('#temp-unit-label').textContent=`MEAN TEMPERATURE · °${unit}`;
}
function selectPlanet(i){current=i;const p=planets[i];document.querySelectorAll('[data-planet]').forEach(b=>{const active=+b.dataset.planet===i;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',active)});$('#hero-name').textContent=p.name;$('.planet-tag .tiny-label').textContent=`0${i+1} / ${p.type.toUpperCase()}`;$('#selected-name').innerHTML=`${p.name} <small>${p.tag}</small>`;$('#distance-stat').innerHTML=`${format(p.distance)} <small>million km</small>`;$('#temp-stat').innerHTML=`${temp(p.temp)} <small>°${unit}</small>`;$('#period-stat').innerHTML=`${format(p.period)} <small>Earth days</small>`;$('#explore-planet').innerHTML=`Explore ${p.name} <span>↗</span>`;$('#orbit-focus').textContent=`TRACKING: ${p.name.toUpperCase()}`;$('#planet-render').setAttribute('aria-label',`Interactive rotating model of ${p.name}`);$('#planet-fallback').style.backgroundImage=`url(assets/${p.file}.jpg)`;updateModel(p);document.dispatchEvent(new CustomEvent('planet-change',{detail:{index:i,planet:p}}));}
document.addEventListener('click',e=>{const b=e.target.closest('[data-planet]');if(b)selectPlanet(+b.dataset.planet)});
document.querySelectorAll('[data-unit]').forEach(b=>b.addEventListener('click',()=>{unit=b.dataset.unit;document.querySelectorAll('[data-unit]').forEach(a=>{a.classList.toggle('selected',a===b);a.setAttribute('aria-pressed',a===b)});renderCharts();selectPlanet(current)}));
function setMotion(){document.body.classList.toggle('motion-paused',!motion);const b=$('#motion-control');b.textContent=motion?'Ⅱ':'▶';b.setAttribute('aria-label',motion?'Pause animations':'Play animations');$('#planet-fallback').style.animationPlayState=motion?'running':'paused';document.dispatchEvent(new CustomEvent('motion-change',{detail:{motion}}))}
$('#motion-control').onclick=()=>{motion=!motion;setMotion()};setMotion();
$('#orbit-play').onclick=()=>{orbitRunning=!orbitRunning;$('#orbit-play').textContent=orbitRunning?'Ⅱ':'▶';$('#orbit-play').setAttribute('aria-label',orbitRunning?'Pause orbital simulation':'Play orbital simulation')};
$('#orbit-speed').oninput=e=>{speed=+e.target.value;$('#speed-label').textContent=speed+'×'};
const dialog=$('#planet-dialog');$('#explore-planet').onclick=()=>{const p=planets[current];$('#dialog-type').textContent=`0${current+1} / ${p.type.toUpperCase()}`;$('#dialog-name').textContent=p.name;$('#dialog-description').textContent=p.description;$('#dialog-facts').innerHTML=[['EQUATORIAL DIAMETER',format(p.diameter)+' km'],['GRAVITY',p.gravity+' m/s²'],['MEAN TEMPERATURE',temp(p.temp)+' °'+unit],['ORBITAL PERIOD',format(p.period)+' days']].map(([k,v])=>`<div><span>${k}</span><strong>${v}</strong></div>`).join('');$('#dialog-link').href=`https://science.nasa.gov/${p.name==='Earth'?'earth':'solar-system/'+p.name.toLowerCase()}/`;dialog.showModal()};$('.dialog-close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
renderCharts();
// A deterministic starfield keeps the scene quiet while planets stay in motion.
const stars=$('#stars'),sc=stars.getContext('2d');function drawStars(){const dpr=Math.min(devicePixelRatio,2),w=innerWidth,h=1050;stars.width=w*dpr;stars.height=h*dpr;sc.setTransform(dpr,0,0,dpr,0,0);let seed=91;function random(){seed=(seed*16807)%2147483647;return seed/2147483647}for(let i=0;i<w*.22;i++){const x=random()*w,y=random()*h,r=random()*.8+.15;sc.beginPath();sc.arc(x,y,r,0,Math.PI*2);sc.fillStyle=`rgba(190,211,230,${random()*.6+.1})`;sc.fill()}}drawStars();
// Schematic orbital radii preserve legibility; orbital speeds share Kepler's relative ordering.
const oc=$('#orbits'),ctx=oc.getContext('2d');let ow=1000,oh=450,orbitTime=0,previous=0,positions=[],orbitZoom=1,orbitTrack=false;
function sizeOrbit(){const r=oc.getBoundingClientRect(),d=Math.min(devicePixelRatio,2);ow=r.width;oh=r.height;oc.width=ow*d;oc.height=oh*d;ctx.setTransform(d,0,0,d,0,0)}
new ResizeObserver(sizeOrbit).observe(oc);
function drawOrbit(ts){if(oc.hidden){requestAnimationFrame(drawOrbit);return;}const dt=Math.min((ts-previous)/1000,.05)||0;previous=ts;if(motion&&orbitRunning&&!document.hidden)orbitTime+=dt*speed*.1;ctx.clearRect(0,0,ow,oh);const cx=ow/2,cy=oh/2-1,max=Math.min(ow*.43,oh*.43);positions=[];let panX=0,panY=0;if(orbitTrack){const r=max*(.18+current*.112),a=current*1.9+orbitTime*Math.pow(365.25/planets[current].period,.5),x=r*Math.cos(a),y=r*.73*Math.sin(a);panX=-(x*Math.cos(-.16)-y*Math.sin(-.16));panY=-(x*Math.sin(-.16)+y*Math.cos(-.16));}ctx.save();ctx.translate(cx,cy);ctx.scale(orbitZoom,orbitZoom);ctx.translate(panX,panY);for(let i=7;i>=0;i--){let r=max*(.18+i*.112);ctx.beginPath();ctx.ellipse(0,0,r,r*.73,-.16,0,Math.PI*2);ctx.strokeStyle=i===current?'#a4ba7448':'#34414e65';ctx.lineWidth=i===current?1.3:.7;ctx.stroke()}
const glow=ctx.createRadialGradient(0,0,1,0,0,40);glow.addColorStop(0,'#f1c66a88');glow.addColorStop(1,'#f1c66a00');ctx.fillStyle=glow;ctx.beginPath();ctx.arc(0,0,40,0,Math.PI*2);ctx.fill();ctx.fillStyle='#f2cc76';ctx.beginPath();ctx.arc(0,0,8,0,Math.PI*2);ctx.fill();ctx.font='7px monospace';ctx.fillStyle='#ad9b72';ctx.textAlign='center';ctx.fillText('SUN',0,23);
planets.forEach((p,i)=>{const r=max*(.18+i*.112),a=i*1.9+orbitTime*Math.pow(365.25/p.period,.5),x=r*Math.cos(a),y=r*.73*Math.sin(a),rx=x*Math.cos(-.16)-y*Math.sin(-.16),ry=x*Math.sin(-.16)+y*Math.cos(-.16),pr=i<4?3.5:i<6?6:4.5;positions.push({x:(rx+panX)*orbitZoom+cx,y:(ry+panY)*orbitZoom+cy,i});if(i===current){ctx.beginPath();ctx.arc(rx,ry,pr+6,0,Math.PI*2);ctx.strokeStyle='#d3ef9b99';ctx.lineWidth=1;ctx.stroke()}ctx.beginPath();ctx.arc(rx,ry,pr,0,Math.PI*2);ctx.fillStyle=p.color;ctx.shadowColor=p.color;ctx.shadowBlur=7;ctx.fill();ctx.shadowBlur=0;if(i===5){ctx.strokeStyle='#b1a587';ctx.beginPath();ctx.ellipse(rx,ry,10,3,-.4,0,Math.PI*2);ctx.stroke()}ctx.font=(i===current?'bold ':'')+'8px "DM Sans", sans-serif';ctx.textAlign='left';ctx.fillStyle=i===current?'#d3ef9b':'#778594';ctx.fillText(p.name,rx+pr+8,ry+3)});ctx.restore();requestAnimationFrame(drawOrbit)}requestAnimationFrame(drawOrbit);
oc.addEventListener('click',e=>{const r=oc.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;const closest=positions.find(p=>Math.hypot(p.x-x,p.y-y)<20);if(closest)selectPlanet(closest.i)});
function setOrbitZoom(next){orbitZoom=Math.max(1,Math.min(3,next));$('#orbit-zoom-label').textContent=orbitZoom.toFixed(1).replace('.0','')+'×';}
$('#orbit-zoom-in').onclick=()=>setOrbitZoom(orbitZoom+.5);$('#orbit-zoom-out').onclick=()=>setOrbitZoom(orbitZoom-.5);
$('#orbit-track').onclick=()=>{orbitTrack=!orbitTrack;$('#orbit-track').setAttribute('aria-pressed',orbitTrack);};
addEventListener('resize',drawStars);
// Enhanced scenes are lazy initialized and share the explorer's selection and motion state.
import('./experience.js').then(({initExperience})=>initExperience({planets,selectPlanet,getState:()=>({current,motion,unit,orbitRunning,speed,orbitZoom,orbitTrack}),registerModel:fn=>{updateModel=fn;fn(planets[current])}})).catch(error=>console.warn('Enhanced experience unavailable',error));
const navigationObserver=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting)document.querySelectorAll('.header nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+entry.target.id));});},{rootMargin:'-15% 0px -55% 0px'});
document.querySelectorAll('main>section[id]').forEach(section=>navigationObserver.observe(section));
